      "severity": "high"
    },
    {
      "issue_type": "weak_edge",
      "description": "C10 (Low confinement) is incorrectly connected as an enabler of H1, even though the open mortar indicates limited confinement rather than a causal driver of a confined explosion.",
      "severity": "medium"
    },
    {
      "issue_type": "weak_edge",
      "description": "Ev1 (scale-up) is connected too directly to H1; the graph should represent the intervening manual handling/stirring step.",
      "severity": "medium"
    },
    {
      "issue_type": "other",
      "description": "H1 evidence is not a verbatim source quote and should be replaced with direct incident-description text.",
      "severity": "medium"
    },
    {
      "issue_type": "schema_mismatch",
      "description": "The available hazard consequence label \"Confined explosion\" is only an approximate fit for this localized detonation in an open mortar, so the node explanation should explicitly acknowledge that limitation.",
      "severity": "low"
    }
  ]
